+                + "Entrada: " + TextFormat.date(reservation.checkIn())
+                + " | Saída: " + TextFormat.date(reservation.checkOut()) + "\n"
+                + "Hóspedes: " + reservation.guests() + "\n");
+        emailSender.send(FINANCE_EMAIL, "Pagamento recebido - reserva " + reservation.id(),
